"""Build the final report from completed registered artifacts, without new rollouts."""
import json
from pathlib import Path
import statistics
import re
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

ROOT=Path('results/research3')


def read(name):return json.loads((ROOT/name).read_text())


def table(stats):
    lines=['| Policy | MSMI/100 | Paired effect | 95% seed CI | Exploratory Holm p |',
           '|---|---:|---:|---|---:|']
    for name,row in sorted(stats['policies'].items(),key=lambda x:-x[1]['primary']['mean']):
        p=row['paired'];ci=p['ci95'];hp=row.get('exploratory_holm_p')
        lines.append(f"| {name} | {row['primary']['mean']:.6f} | {p['mean']:+.6f} | [{ci[0]:+.6f}, {ci[1]:+.6f}] | {hp:.4f} |" if hp is not None else f"| {name} | {row['primary']['mean']:.6f} | reference | — | — |")
    return '\n'.join(lines)


def main():
    screen,focus,selection,confirmation=[read(n+'_statistics.json') for n in ('screen','focus','selection','confirmation')]
    freeze=read('freeze.json');name=freeze['policy'];selected=confirmation['policies'][name];base=confirmation['policies']['greedy']
    p=selected['paired'];ci=p['ci95']
    claim='The registered confirmation establishes a positive mean effect over shipped greedy on these six public families.' if ci[0]>0 else 'The registered confirmation does not establish superiority over shipped greedy.'
    practical='The interval excludes the targeted +0.10 improvement.' if ci[1]<.10 else 'The targeted +0.10 improvement is not excluded, but is not established unless the interval lower bound exceeds +0.10.'
    mechanism=read('confirmation_mechanisms.json');tot=mechanism['totals'];prod=read('production_selected.json');lp=read('lp_headroom.json')
    lines=[f'# Round 3: sequential matching research\n\n{claim}',
       f'The frozen candidate is `{name}`, config `{json.dumps(freeze["configuration"],sort_keys=True)}`. Greedy scores {base["primary"]["mean"]:.6f} MSMI/100; candidate {selected["primary"]["mean"]:.6f}. Paired effect {p["mean"]:+.6f}, registered 95% seed-cluster CI [{ci[0]:+.6f}, {ci[1]:+.6f}], two-sided p={p["p_two_sided"]}. {practical} Nonsignificance does not establish equivalence. Selection estimates and exploratory rankings do not establish that this candidate is best.',
       '## Preservation and evidence boundary',
       'The previous completed extension remains negative/inconclusive: greedy .372917, simple_fifo .331250, difference −.041667, CI [−.091068,+.007735]. Its common positive score cannot rank dyads differently through updates; auxiliary diagnostics still execute. FIFO schedules are identical and favorable deadline outcomes plausibly contributed to development estimates. Those facts were independently reproduced. No_learning_fifo and terminal_soft did not receive their own old confirmation.',
       'Inherited root policy.py and extended_policy.py differed from their old freeze hashes at this round’s start. Initial bytes were fingerprinted and preserved; exact old frozen versions were recovered into research3/recovered_frozen from a git checkpoint. No old result, report, source, archive or manifest was overwritten. All eight old archives and 1,687 raw members verified. The new greedy adapter directly calls shipped kit mechanisms and reproduced an old action digest. Root policy.py remains the inherited research2 candidate, not this round’s greedy comparator.',
       'Research2’s asserted proof of +.10 contradicted its own negative result, and its fast scripts omitted official follow-up. Those claims were rejected; all planned/exposed seeds were excluded. See [critic audit](CRITIC.md), [seed inventory](../results/research3/seed_inventory.json), and [decisions](DECISIONS.md).',
       '## Bottlenecks and influenceable losses',
       'Independent old-confirmation counts: greedy 17,954 introductions; 7,419 fail reciprocal response; among 10,535 both-respond pairs, 8,107 fail mutual acceptance. Of 2,428 mutual accepts, 579 dates cancel; 1,849 dates yield 727 reciprocal second nonresponses and 611 negative pairs among 1,122 both-respond seconds. Of 511 positive pauses, 332 miss date or feedback qualification, leaving 179 qualified. These are pooled counts with stage-specific denominators, not independent assignment-level tests.',
       'Public date cancellation probability is .22, feedback qualification .36 conditional on both-positive outcomes, and delayed date qualification671/686. Assigning earlier does not repair relative deadlines. Pair quality, clarification timing and future opportunity availability can change response/acceptance/pause counts; deadline draws themselves cannot be predicted from permitted inputs.',
       'A new deterministic timing lemma shows that a currently available endpoint has every scheduled event from each prior introduction already observed: failed introductions release on assignment+8 after the day+7 response maximum; mutual introductions release on date+6 after the date+5 feedback maximum. Legal later introductions cannot overwrite an unresolved busy interval. The old48-world audit found zero violations in458,829 available-endpoint invocations. Thus pending-survival corrections cannot change this round’s current legal-edge actor response estimate; global learning from unavailable actors is a separate question. See [available-feedback theorem](AVAILABLE_FEEDBACK_THEOREM.md).',
       'Static privileged old development graphs average only74.625 nonblocked nonisolated endpoints in ordinary worlds and30.625 in sparse worlds. Every nonblocked member eventually becomes verified under FIFO; final verification completion is not the dominant missed-opportunity count. The dynamic edge-day audit separates not-arrived, used, exited, paused, busy, unverified and available states using an explicit precedence. It is descriptive and privileged, not a causal opportunity bound. See [forensics](FORENSICS.md).',
       '## Registered experiments and candidate decisions',
       'Training used old seeds1001–1005, validation1006–1008, prospective assignment snapshots and public resolved labels only. Screen70001–70012 used13 candidates; focused development71001–71032 used the registered top three plus mandatory architecture controls/ablations; selection72001–72020 used its fixed rule. Confirmation code/config and sample were frozen before seeds73001 onward. Six families sharing a seed were always clustered together. No fitting or retuning after screening, and no confirmation extension.',
       '### Exploratory screening\n\n'+table(screen),
       '### Focused development and ablations\n\n'+table(focus),
       '### Independent candidate selection\n\n'+table(selection),
       f'Selected `{name}` by the registered engineering-cost preference within .025 of the best selection mean. This band does not mean equivalence. Confirmation fixed n={freeze["confirmation_n"]} seed clusters from pilot SD floor/estimate {freeze["planning_sd"]:.6f}; uncapped planning n={freeze["uncapped_power_n"]}. The practical target was +.10. Power planning is approximate for rare discrete rewards.',
       '### Frozen confirmation',
       f'Paired bootstrap sensitivity95% [{selected["bootstrap95"][0]:+.6f}, {selected["bootstrap95"][1]:+.6f}], standardized paired effect {p["standardized"]}. All planned cells must be valid with zero optimized-path fallback before analysis. Failures are retained and disqualify conclusions rather than silently removed.',
       '| Family | Candidate | Greedy | Difference |\n|---|---:|---:|---:|',
       *[f'| {v} | {selected["scenario_means"][v]:.6f} | {base["scenario_means"][v]:.6f} | {selected["scenario_means"][v]-base["scenario_means"][v]:+.6f} |' for v in selected['scenario_means']],
       '| Secondary metric | Candidate | Greedy |\n|---|---:|---:|',
       f'| Mean episode coverage | {selected["mean_coverage"]:.6f} | {base["mean_coverage"]:.6f} |',
       f'| Mean episode ask cost | {selected["totals"]["ask_cost"]/(6*freeze["confirmation_n"]):.3f} | {base["totals"]["ask_cost"]/(6*freeze["confirmation_n"]):.3f} |',
       f'| Pooled mutual acceptance / assignments | {selected["totals"]["mutual_acceptances"]/selected["totals"]["assignments"]:.6f} | {base["totals"]["mutual_acceptances"]/base["totals"]["assignments"]:.6f} |',
       f'| Pooled dates / mutual acceptance | {selected["totals"]["dates"]/max(1,selected["totals"]["mutual_acceptances"]):.6f} | {base["totals"]["dates"]/max(1,base["totals"]["mutual_acceptances"]):.6f} |',
       'These pooled conditional rates differ from means of episode ratios. Raw denominators are retained; secondary metrics carry no separate confirmatory superiority claim.',
       '## Mechanism evidence, disagreements and alternatives',
       f'Confirmation introductions {tot[name]["assignments"]} versus {tot["greedy"]["assignments"]}, positive pauses {tot[name]["positive_pause"]} versus {tot["greedy"]["positive_pause"]}, qualified {tot[name]["qualified"]} versus {tot["greedy"]["qualified"]}, deadline disqualified {tot[name]["deadline_disqualified"]} versus {tot["greedy"]["deadline_disqualified"]}. Representative full traces, paired count effects, query schedule equality, busy duration and repeat endpoint counts are in [confirmation mechanisms](../results/research3/confirmation_mechanisms.json).',
       'These chosen-trajectory changes do not identify a causal mechanism. Different dyads/days change hashed outcome streams; common worlds do not share every downstream draw. Architecture controls isolate score/query differences at the policy level, while descriptive occupancy/pause/deadline comparisons can still reflect chance and endogenous future assignments. The critic’s strongest alternatives and resolutions appear in SCREEN_REVIEW.md and FINAL_REVIEW.md. No retrospective truth enters candidate features.',
       'A controlled final-day intervention establishes a narrower result: with collision-free introduction IDs and full follow-up, appending a legal edge between unmatched available endpoints on day59 leaves every existing outcome unchanged and can only add terminal reward. The zero-score filter therefore has no final-day continuation justification. Across24 already examined trajectories,37 such edges were added; existing events were byte-identical, realized additional qualification was zero and the numerical conditional expected total was .159206. This is small, rare-event headroom, not a confirmed substantial gain. No augmented candidate entered the frozen selection/confirmation. See [final-day audit](FINAL_DAY_AUGMENTATION.md).',
       '## Prediction, learning and oracle headroom',
       'Prediction models were compared on identical prospective greedy examples, not their own selected populations. The old split contains only14 terminal positives across three validation clusters; response shrinkage’s favorable proper-score/AUC points were exploratory. Frozen offline ridge failed to beat population validation point proper scores. The focused32-seed common-cohort audit supplies full-funnel logloss/Brier, calibration uncertainty and scenario/missingness/time/history slices. It does not fit models or evaluate confirmation for selection. See [prediction audit](PREDICTION_AUDIT.md).',
       'Stored raw snapshot prediction values are auxiliary inherited integrated-prior diagnostics with a uniform three-regime mixture, not each candidate’s forecast or the new six-family population prior. Independent audits recompute named forecasts on identical examples; recording diagnostics do not enter actions. See [prospective data contract](PROSPECTIVE_DATA_CONTRACT.md).',
       'The learning-paradigm assessment implements supervised offline ridge, public model integration, online response shrinkage, graph structure/scarcity, busy-duration allocation and exact tiny model-based planning. Large self-supervised/unsupervised feature models lack fresh generator cross-feature signal; offline policy importance sampling lacks logged propensities/action coverage; full model-free RL and bandit reductions are unjustified by the sparse coupled data here. These are scoped decisions, not impossibility theorems. Strong nonlearning controls remain mandatory.',
       'Privileged diagnostic levels separately disclose actor/family parameters, soft truth, or free hard truth; none sees future random outcomes.120 old-world greedy oracle episodes did not establish superiority. Stronger information did not monotonically improve realized reward; these heuristics are not optimized dynamic bounds. Tiny exact future-state planning is exact only for specified toy models.',
       f'The inherited optimistic capacity LP on old seed1001 has mean bound candidate {statistics.mean(r["bound_msmi_per100"] for r in lp["rows"]):.6f} MSMI/100 across six families, sparse {next(r["bound_msmi_per100"] for r in lp["rows"] if r["variant"]=="sparse"):.6f}. It reveals latent parameters/arrivals/exits and all nondeclined hard truth, relaxes schedules fractionally and drops retirement/extra occupancy. Numerical quadrature and fresh-stream assumptions apply. One seed and a loose expected bound cannot quantify attainable population improvement.',
       '## Mathematical and empirical classification',
       '| Evidence class | Supported scope |\n|---|---|\n| Proven mathematical results | Available endpoints have all prior-introduction events resolved; final-day legal augmentation weakly adds reward under collision-free IDs/full follow-up. Three soft fields are absent from current-edge outcome/eligibility laws; goal/pace/conversation equality increases fixed-parameter immediate funnel probability. Inherited scoped pause identity/FIFO invariance retained. No global policy optimality follows. |\n| Exact simulator calculations | Legal bundle/soft costs,11 hard constraints,60+40 horizon, reused shared effect/response parameters, .36 feedback factor and delayed tail671/686. Exact uniform-prior response posterior moments under stated response sampling model. |\n| Exact simplified-model solutions | Rational DP counterexamples refute universal greedy, scarcity, occupancy-ratio and waiting rules. Finite81-pattern scoring enumeration finds25/16 population-throughput ranking inversions before/afterday35 despite identical B actions. |\n| Empirical findings | Registered paired seed reward, identical-cohort predictive scores, finite resource/parity tests, descriptive funnel and oracle trajectories. |\n| Approximation assumptions | Gaussian quadrature, uniform missing-feature priors after selection, moment-matched Beta shrinkage, fixed prior regime mixture, logistic observational fit and nonseparable occupancy heuristic. Pending-survival omission is irrelevant for currently legal actor ranking under the proved source timing lemma. |\n| Unvalidated hypotheses | Exact uniform response posterior ranking, better history-conditioned feature beliefs, component-local dynamic planners, coordinated query/assignment bundles and transfer beyond these public families. |',
       '## Production and reproduction',
       f'Selected executable: `python3 -m research3.policy --candidate {name}`. The root policy.py is not replaced. Selected full seed101 direct/subprocess/restricted-container replay records {prod["valid"]} validity and action/outcome equivalence. Image inspect size {prod["image"]["size_bytes"]} bytes, below the documented2GiB limit. All candidates passed constructed200-node dense container parity; memory2 bytes. Actual cgroup probe records2cores,1GiB,64PIDs, unprivileged UID, read-only root and blocked network egress.',
       f'Confirmation measured in-process mean/p95/p99/max seconds {selected["latency_seconds"]}; peak request {selected["peak_request_bytes"]} bytes; returned memory {selected["peak_memory_bytes"]} bytes. Startup/container timings are separate. The7second optimized alarm, bounded request and empty legal fallback do not constitute a universal10second guarantee for arbitrary machines/requests. Tests cover actual interruption, outer timers, malformed/oversized/pending inputs and no solver dependence. Per-call stderr fallback warnings are captured for the selected production replay.',
       'No old source or artifact was changed. Lossless archives preserve raw trajectories, with verified non-overwriting restoration. Commands/versions/compute, seed partitions, written cross-reviews, independent replays, source/config hashes and final manifest are included. See [reproduction instructions](REPRODUCTION.md). Primary-source novelty assessment in [literature](LITERATURE.md) attributes established methods; broad novelty is uncertain.',
       '## Most informative unresolved question',
       'Can coordinated clarification and assignment timing increase expected positive pauses among scarce legal endpoints, after holding score quality fixed and accounting jointly for future occupancy? Current static oracle and sparse learning evidence does not solve this dynamic question. Any next round needs fresh seeds and a new registered fixed confirmation, rather than extending this one.']
    lines.append('Focused control contrasts: goal_queries minus public_weight −.005208 (95% CI [−.054629,+.044212]); offline minus population −.052083 (CI [−.093708,−.010459], exploratory Holm p=.063440). None establishes adjusted benefit. On the identical 14,444 greedy assignments from32 seeds, all10 terminal proper-score contrasts have Holm p≥.19577. The completed confirmation contains480/480 valid episodes with zero failures and optimized fallbacks. The interrupted host run resumed only84 missing registered cells; original partial rows and frozen hashes are preserved.')
    report=re.sub(r'(\|[^\n]*\|)\n\n(?=\|)', r'\1\n', '\n\n'.join(lines))
    Path('research3/FINAL_REPORT.md').write_text(report+'\n')
    names=[n for n in screen['policies'] if n!='greedy'];names.sort(key=lambda n:screen['policies'][n]['paired']['mean'])
    fig,axes=plt.subplots(1,2,figsize=(12,6),gridspec_kw={'width_ratios':[2,1]})
    vals=[screen['policies'][n]['paired']['mean'] for n in names]
    low=[v-screen['policies'][n]['paired']['ci95'][0] for n,v in zip(names,vals)]
    high=[screen['policies'][n]['paired']['ci95'][1]-v for n,v in zip(names,vals)]
    axes[0].errorbar(vals,names,xerr=[low,high],fmt='o');axes[0].axvline(0,color='grey');axes[0].set_title('Exploratory screen;12seed clusters');axes[0].set_xlabel('Paired effect MSMI/100; unadjusted95%CI')
    axes[1].errorbar([p['mean']],[name],xerr=[[p['mean']-ci[0]],[ci[1]-p['mean']]],fmt='o',color='black');axes[1].axvline(0,color='grey');axes[1].axvline(.10,linestyle='--',color='grey');axes[1].set_title(f'Frozen confirmation;{freeze["confirmation_n"]}clusters');axes[1].set_xlabel('Paired effect MSMI/100;95%CI');fig.tight_layout();fig.savefig(ROOT/'policy_effects.png',dpi=160);plt.close(fig)


if __name__=='__main__':main()
